{
  "findings": [
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "The FTC complaint alleges Adobe's early termination fee can be as much as 50 percent of the remaining monthly payments if canceled within the first year.",
      "stance": "risk",
      "quote": "FTC's complaint details how Adobe steers consumers towards its \"annual paid monthly\" subscription plan without adequately informing them about the ETF, which can be as much as 50 percent of the remaining monthly payments if canceled within the first year.[[3]](#cite-adobe-3)"
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "Adobe buried the early termination fee in fine print and behind small icons on its website.",
      "stance": "risk",
      "quote": "This fee is often hidden in fine print or behind small icons on Adobe's website. Consumers reported to FTC and the Better Business Bureau that they were unaware of the ETF or the requirement to keep the subscription for a year.[[3]](#cite-adobe-3)"
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "The settlement requires Adobe to clearly disclose any early termination fee and how it is calculated before enrolling customers.",
      "stance": "mitigation",
      "quote": "Adobe must also clearly disclose any ETF and how it is calculated before enrolling customers.[[7]](#doj-adobe-rosca-settlement)"
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "The settlement requires Adobe to give subscribers easy ways to cancel.",
      "stance": "mitigation",
      "quote": "The Justice Department says the order requires Adobe to give subscribers easy ways to cancel.[[7]](#doj-adobe-rosca-settlement)"
    },
    {
      "ref": "[D526]",
      "area": "money",
      "claim": "For free trials longer than seven days, the settlement requires Adobe to send a reminder before the paid plan starts.",
      "stance": "mitigation",
      "quote": "It must remind customers before a free trial longer than seven days turns into a paid plan with an ETF.[[7]](#doj-adobe-rosca-settlement)"
    },
    {
      "ref": "[D526]",
      "area": "developer_record",
      "claim": "The FTC filed a complaint against Adobe and two executives, Maninder Sawhney and David Wadhwani, in June 2024.",
      "stance": "neutral",
      "quote": "Federal Trade Commission (FTC) has filed a complaint[[1]](#cite-ftc-1) against Adobe and two of its executives, Maninder Sawhney and David Wadhwani, in the U.S. District Court for the Northern District of California."
    },
    {
      "ref": "[D526]",
      "area": "developer_record",
      "claim": "Adobe denies wrongdoing and disagrees with the government's claims.",
      "stance": "neutral",
      "quote": "Adobe said it disagrees with the government's claims and denies any wrongdoing.[[8]](#reuters-adobe-settlement-2026)"
    }
  ]
